            withContext(Dispatchers.Main.immediate) {
                handleImageSaveResult(success, successMessage = "实况照片已保存到相册")
            }
        }
    } else {
        pendingSaveAction = { requestSaveMotionPhoto(imageUrl, videoUrl) }
        storagePermission.request()
    }
}

